// VIN-651 13.11.26 (PR #461, push 13.11 16:59 CET): ticket tag on the 3 pricing billing-terms keys. Descriptions already set by dev - kept.
const IDS = ["980021020", "980021022"];
const PLAN = {"980021020": {"tags": ["VIN-651"]}, "980021021": {"tags": ["VIN-651"]}, "980021022": {"tags": ["VIN-651"]}};
return [{ json: { project_id: '2944050668d5010cbd95e8.36175908', plan: PLAN, key_ids: IDS } }];

// Guards: skip archived; tags merged (only missing ones); description and ES written ONLY when empty (ES as unverified).
// desc_old/desc_new replaces a description ONLY when the live text is exactly desc_old.
// tr_replace {lang: [old, new]} replaces a target ONLY when the live text is exactly old (written unverified).
const p = $('Params').first().json; const keys = ($input.first().json.keys) || [];
const byId = {}; for (const k of keys) { byId[k.key_id] = k; }
const out = []; const skipped = []; const expected = {}; const expDesc = {}; const expTr = {}; const current = {};
for (const id of p.key_ids) {
  const k = byId[id]; if (!k || k.is_archived) { skipped.push({ id: id, why: 'missing/archived' }); continue; }
  const pl = p.plan[id] || {};
  const item = { key_id: Number(id) };
  const trs = [];
  current[id] = (k.translations || []).map(function (t) { return { lang: t.language_iso, text: t.translation, by: t.modified_by_email, at: t.modified_at }; });
  const missing = (pl.tags || []).filter(function (t) { return (k.tags || []).indexOf(t) === -1; });
  if (missing.length) { item.tags = missing; item.merge_tags = true; }
  if (pl.desc) {
    if (!String(k.description || '').trim()) { item.description = pl.desc; expDesc[id] = pl.desc; }
    else { skipped.push({ id: id, why: 'description not empty - kept' }); }
  }
  if (pl.desc_new) {
    if (k.description === pl.desc_old) { item.description = pl.desc_new; expDesc[id] = pl.desc_new; }
    else { skipped.push({ id: id, why: 'description changed by someone else - kept' }); }
  }
  if (pl.es) {
    const es = (k.translations || []).filter(function (t) { return t.language_iso === 'es'; })[0];
    const cur = es ? String(es.translation || '').trim() : '';
    if (!cur) { trs.push({ language_iso: 'es', translation: pl.es, is_unverified: true }); expected[id] = pl.es; }
    else { skipped.push({ id: id, why: 'es not empty - kept' }); }
  }
  if (pl.tr_replace) {
    for (const lang of Object.keys(pl.tr_replace)) {
      const pair = pl.tr_replace[lang];
      const t = (k.translations || []).filter(function (x) { return x.language_iso === lang; })[0];
      if (t && t.translation === pair[0]) { trs.push({ language_iso: lang, translation: pair[1], is_unverified: true }); expTr[id + ':' + lang] = pair[1]; }
      else { skipped.push({ id: id, lang: lang, why: 'live text differs from expected old - kept', live: t ? t.translation : null }); }
    }
  }
  if (trs.length) { item.translations = trs; }
  if (item.tags || item.translations || item.description) { out.push(item); }
}
if (out.length === 0) { throw new Error('Nothing to write: ' + JSON.stringify(skipped)); }
return [{ json: { body: { keys: out }, skipped: skipped, expected: expected, exp_desc: expDesc, exp_tr: expTr, current: current, plan: out.map(function (x) { return x.key_id; }) } }];

const p = $('Params').first().json; const B = $('Build').first().json;
const byId = {}; for (const it of $input.all()) { for (const k of ((it.json && it.json.keys) || [])) { byId[k.key_id] = k; } }
const res = B.plan.map(function (id) {
  const k = byId[id] || {}; const tags = k.tags || []; const pl = p.plan[String(id)] || {};
  const trs = k.translations || [];
  const es = trs.filter(function (t) { return t.language_iso === 'es'; })[0] || {};
  const okT = (pl.tags || []).every(function (t) { return tags.indexOf(t) !== -1; });
  const exp = B.expected[String(id)]; const okE = !exp || es.translation === exp;
  const expD = (B.exp_desc || {})[String(id)]; const okD = !expD || k.description === expD;
  const trCheck = Object.keys(B.exp_tr || {}).filter(function (x) { return x.split(':')[0] === String(id); }).map(function (x) { const lang = x.split(':')[1]; const t = trs.filter(function (y) { return y.language_iso === lang; })[0] || {}; return { lang: lang, ok: t.translation === B.exp_tr[x], text: t.translation, unverified: t.is_unverified }; });
  const okR = trCheck.every(function (x) { return x.ok; });
  return { id: id, ok: okT && okE && okD && okR, tr: trCheck, tags: tags, description: k.description };
});
const bad = res.filter(function (x) { return !x.ok; });
return [{ json: { ok: bad.length === 0, n: res.length, tr_written: Object.keys(B.exp_tr || {}).length, desc_written: Object.keys(B.exp_desc || {}).length, bad: bad, skipped: B.skipped, sample: res.slice(0, 2) } }];

// Lokalise returned 500 on a 40-key PUT: send 10 keys per call.
const out = [];
for (const it of $input.all()) { const ks = it.json.body.keys; for (let i = 0; i < ks.length; i += 10) { out.push({ json: { body: { keys: ks.slice(i, i + 10) } } }); } }
return out;
